ACTIVATION_X_MIN = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0

def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }

class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}

MEM = Memory()

def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(5.0) * abs(gy)

def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)

def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_streak": 0,
            "in_blind_zone": False,
        }
    state = MEM.data["initial_state"]
    cfg = _control_cfg(sandbox)
    pd = sandbox.get_agent_position()
    vx_p, vy_p = sandbox.get_agent_velocity()
    x, y = pd[0], pd[1]
    ty = 1.5
    w_comp = _weight_comp(sandbox)
    front, up, down = sandbox.get_whisker_readings()

    # Check for whisker blind zone (all maxed)
    in_blind_zone = front >= 3.0 and up >= 3.0 and down >= 3.0
    state["in_blind_zone"] = in_blind_zone

    if state["phase"] == "APPROACH":
        if x < 5.0:
            fx = 15.0
        else:
            fx = 10.0 * (7.0 - x) - 5.0 * vx_p
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        # Check for activation zone entry with zero velocity
        if cfg["act_lo"] <= x <= cfg["act_hi"] and abs(vx_p) < 0.001:
            state["phase"] = "UNLOCK"
            state["t"] = 0
            state["unlock_streak"] = 0
    elif state["phase"] == "UNLOCK":
        # Enforce strict backward force (-35.0 N)
        fx_cmd = -35.0
        fy_cmd = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        spd = math.hypot(vx_p, vy_p)
        # Adjust for whisker blind zone by applying lateral force to exit
        if state["in_blind_zone"]:
            # Move robot out of blind zone by applying lateral force
            if x < 9.0:
                fx_cmd += 10.0  # Push right
            elif x > 9.0:
                fx_cmd -= 10.0  # Push left
        # Ensure commanded force is below threshold
        if fx_cmd < -34.0 and spd < cfg["bspd"]:
            state["unlock_streak"] += 1
            if state["unlock_streak"] >= 5:
                state["phase"] = "ESCAPE"
                state["unlock_streak"] = 0
        else:
            state["unlock_streak"] = 0
        fx, fy = fx_cmd, fy_cmd
    elif state["phase"] == "ESCAPE":
        fx = 15.0
        fy = 50.0 * (ty - y) - 20.0 * vy_p + w_comp
        # Adjust for proximity to internal walls
        if 8.5 < x < 9.5:
            if front < 2.5:
                fy += -10.0 * (front - 2.5)
        if 13.5 < x < 14.5:
            if front < 2.5:
                fy += -10.0 * (front - 2.5)
        # Check if in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

